  status: 'On Track' | 'Behind' | 'Ahead';
  prescribedExercises: Exercise[];
  logs: DailyLog[];
  benchmarkRom: number[]; // Expected ROM per week
}

export interface AnalysisResult {
  summary: string;
  riskLevel: 'Low' | 'Medium' | 'High';
  recommendations: string[];
}

