import { GoogleGenAI } from "@google/genai";
import { Patient } from '../types';

const getClient = () => {
  const apiKey = process.env.API_KEY;
  if (!apiKey) {
    throw new Error("API Key not found");
  }
  return new GoogleGenAI({ apiKey });
};

export const analyzePatientProgress = async (patient: Patient): Promise<string> => {
  const ai = getClient();

  // Construct a prompt based on the patient's data
  const prompt = `
    You are an expert physiotherapist assistant. Analyze the following patient data and provide a concise clinical progress note.

    Patient: ${patient.name}
    Injury: ${patient.injury}

    Prescribed Exercises:
    ${patient.prescribedExercises.map(e => `- ${e.name} (Target ROM: ${e.targetRom}°, Target Reps: ${e.targetReps})`).join('\n')}

    Recent Progress Logs (Last 5 entries):
    ${patient.logs.slice(-5).map(l => `- Date: ${l.date}, Pain (1-10): ${l.painScore}, ROM: ${l.maxRom}°, Reps: ${l.repsCompleted}, Notes: ${l.notes}`).join('\n')}

    Benchmark Goal for current week: Approaching 120 degrees flexion.

    Please provide:
    1. A summary of their progress trend (improving, plateauing, or regressing).
    2. Specific observations about their pain vs. ROM.
    3. Recommendations for the physiotherapist (e.g., adjust intensity, check form, referral).

    Format the output as a Markdown block. Keep it professional and clinical.
  `;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-2.5-flash',
      contents: prompt,
      config: {
        temperature: 0.3, // Lower temperature for more analytical/consistent results
      }
    });

    return response.text || "Unable to generate analysis at this time.";
  } catch (error) {
    console.error("Error calling Gemini:", error);
    return "Error generating analysis. Please check your API configuration.";
  }
};

import React, { useState } from 'react';
import { LineChart, Line, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, Legend } from 'recharts';
import { Activity, AlertTriangle, FileText, CheckCircle, ChevronLeft, Bot } from 'lucide-react';
import { Patient } from '../types';
import { analyzePatientProgress } from '../services/geminiService';
import ReactMarkdown from 'react-markdown';

interface PhysioDashboardProps {
  patient: Patient;
  onBack: () => void;
}

export const PhysioDashboard: React.FC<PhysioDashboardProps> = ({ patient, onBack }) => {
  const [analysis, setAnalysis] = useState<string | null>(null);
  const [isAnalyzing, setIsAnalyzing] = useState(false);

  const chartData = patient.logs.map((log, index) => ({
    date: log.date.split('-').slice(1).join('/'), // MM/DD
    rom: log.maxRom,
    pain: log.painScore,
    benchmark: patient.benchmarkRom[Math.min(index, patient.benchmarkRom.length - 1)] || 135
  }));

  const handleAIAnalysis = async () => {
    setIsAnalyzing(true);
    try {
      const result = await analyzePatientProgress(patient);
      setAnalysis(result);
    } catch (e) {
      setAnalysis("Failed to connect to AI service.");
    } finally {
      setIsAnalyzing(false);
    }
  };

  return (
    <div className="flex flex-col h-full bg-slate-50">
      {/* Header */}
      <header className="bg-white border-b border-slate-200 px-6 py-4 flex items-center justify-between sticky top-0 z-10">
        <div className="flex items-center gap-4">
          <button onClick={onBack} className="p-2 hover:bg-slate-100 rounded-full transition-colors text-slate-500">
            <ChevronLeft size={24} />
          </button>
          <div>
            <h1 className="text-xl font-bold text-slate-800">{patient.name}</h1>
            <div className="flex items-center gap-2 text-sm text-slate-500">
              <span className="bg-blue-100 text-blue-700 px-2 py-0.5 rounded-full text-xs font-medium">
                {patient.injury}
              </span>
              <span>Started: {patient.startDate}</span>
            </div>
          </div>
        </div>
        <div className="flex items-center gap-2">
           <span className={`px-3 py-1 rounded-full text-sm font-medium ${
             patient.status === 'Behind' ? 'bg-red-100 text-red-700' : 'bg-green-100 text-green-700'
           }`}>
             Status: {patient.status}
           </span>
        </div>
      </header>

      <main className="flex-1 overflow-auto p-6 max-w-7xl mx-auto w-full">
        <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">

          {/* Main Chart Section */}
          <div className="lg:col-span-2 space-y-6">
            <div className="bg-white p-6 rounded-xl shadow-sm border border-slate-100">
              <div className="flex items-center justify-between mb-6">
                <h3 className="text-lg font-semibold text-slate-800 flex items-center gap-2">
                  <Activity className="text-blue-500" size={20} />
                  Range of Motion (ROM) Recovery
                </h3>
              </div>
              <div className="h-[300px] w-full">
                <ResponsiveContainer width="100%" height="100%">
                  <LineChart data={chartData} margin={{ top: 5, right: 30, left: 20, bottom: 5 }}>
                    <CartesianGrid strokeDasharray="3 3" stroke="#f1f5f9" />
                    <XAxis dataKey="date" stroke="#94a3b8" fontSize={12} tickLine={false} />
                    <YAxis stroke="#94a3b8" fontSize={12} tickLine={false} label={{ value: 'Degrees (°)', angle: -90, position: 'insideLeft', style: { fill: '#94a3b8' } }} />
                    <Tooltip 
                      contentStyle={{ backgroundColor: '#fff', borderRadius: '8px', border: '1px solid #e2e8f0', boxShadow: '0 4px 6px -1px rgb(0 0 0 / 0.1)' }}
                    />
                    <Legend />
                    <Line type="monotone" dataKey="rom" name="Actual ROM" stroke="#3b82f6" strokeWidth={3} dot={{ r: 4 }} activeDot={{ r: 8 }} />
                    <Line type="monotone" dataKey="benchmark" name="Target Goal" stroke="#cbd5e1" strokeWidth={2} strokeDasharray="5 5" dot={false} />
                  </LineChart>
                </ResponsiveContainer>
              </div>
            </div>

            <div className="bg-white p-6 rounded-xl shadow-sm border border-slate-100">
               <h3 className="text-lg font-semibold text-slate-800 mb-4 flex items-center gap-2">
                 <AlertTriangle className="text-amber-500" size={20} />
                 Pain Levels Trend
               </h3>
               <div className="h-[200px] w-full">
                <ResponsiveContainer width="100%" height="100%">
                  <LineChart data={chartData}>
                    <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#f1f5f9" />
                    <XAxis dataKey="date" hide />
                    <YAxis domain={[0, 10]} stroke="#94a3b8" fontSize={12} tickLine={false} />
                    <Tooltip />
                    <Line type="step" dataKey="pain" name="Pain Score" stroke="#f59e0b" strokeWidth={2} dot={{ fill: '#f59e0b' }} />
                  </LineChart>
                </ResponsiveContainer>
               </div>
            </div>
          </div>

          {/* Sidebar / AI Analysis */}
          <div className="space-y-6">
            {/* AI Action Card */}
            <div className="bg-gradient-to-br from-indigo-600 to-purple-700 rounded-xl p-6 text-white shadow-lg">
              <div className="flex items-start justify-between mb-4">
                <div>
                  <h3 className="text-lg font-bold flex items-center gap-2">
                    <Bot size={24} />
                    AI Clinical Assistant
                  </h3>
                  <p className="text-indigo-100 text-sm mt-1">
                    Analyze patient logs against recovery benchmarks using Gemini.
                  </p>
                </div>
              </div>

              {!analysis ? (
                <button 
                  onClick={handleAIAnalysis}
                  disabled={isAnalyzing}
                  className="w-full py-3 bg-white text-indigo-700 rounded-lg font-semibold hover:bg-indigo-50 transition-colors disabled:opacity-70 disabled:cursor-not-allowed flex justify-center items-center gap-2"
                >
                  {isAnalyzing ? (
                    <>
                      <div className="w-5 h-5 border-2 border-indigo-700 border-t-transparent rounded-full animate-spin"></div>
                      Analyzing...
                    </>
                  ) : (
                    <>Generate Clinical Report</>
                  )}
                </button>
              ) : (
                <div className="bg-white/10 backdrop-blur-sm rounded-lg p-4 mt-4 text-sm animate-in fade-in slide-in-from-bottom-4">
                  <div className="flex justify-between items-center mb-2">
                     <span className="font-semibold text-indigo-100">Generated Insight</span>
                     <button onClick={() => setAnalysis(null)} className="text-xs hover:underline text-indigo-200">Reset</button>
                  </div>
                  <div className="prose prose-invert prose-sm max-h-[400px] overflow-y-auto custom-scrollbar">
                     <ReactMarkdown>{analysis}</ReactMarkdown>
                  </div>
                </div>
              )}
            </div>

            {/* Recent Logs List */}
            <div className="bg-white p-6 rounded-xl shadow-sm border border-slate-100">
              <h3 className="text-lg font-semibold text-slate-800 mb-4 flex items-center gap-2">
                <FileText className="text-slate-400" size={20} />
                Recent Logs
              </h3>
              <div className="space-y-4">
                {patient.logs.slice().reverse().slice(0, 4).map((log, i) => (
                  <div key={i} className="flex items-start gap-3 pb-3 border-b border-slate-50 last:border-0 last:pb-0">
                    <div className="mt-1">
                      <div className="w-2 h-2 rounded-full bg-blue-500"></div>
                    </div>
                    <div>
                      <p className="text-sm font-medium text-slate-800">{log.date}</p>
                      <p className="text-xs text-slate-500 mt-0.5">ROM: {log.maxRom}° • Pain: {log.painScore}/10</p>
                      {log.notes && (
                        <p className="text-xs text-slate-600 italic mt-1">"{log.notes}"</p>
                      )}
                    </div>
                  </div>
                ))}
              </div>
            </div>
          </div>

        </div>
      </main>
    </div>
  );
};

import React, { useState, useRef, useEffect } from 'react';
import { Camera, ArrowLeft, Play, CheckCircle2, ChevronRight, AlertCircle, RefreshCw } from 'lucide-react';
import { Patient, Exercise } from '../types';

interface PatientAppProps {
  patient: Patient;
  onBack: () => void;
}

export const PatientApp: React.FC<PatientAppProps> = ({ patient, onBack }) => {
  const [activeExercise, setActiveExercise] = useState<Exercise | null>(null);
  const [isExercising, setIsExercising] = useState(false);
  const [sessionComplete, setSessionComplete] = useState(false);

  // Exercise Session State
  const [reps, setReps] = useState(0);
  const [feedback, setFeedback] = useState<string>("Align your body in the frame");
  const [currentAngle, setCurrentAngle] = useState(0);
  const [painScore, setPainScore] = useState(5);

  const videoRef = useRef<HTMLVideoElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);

  // Simulation Logic
  useEffect(() => {
    let interval: any;

    if (isExercising && !sessionComplete) {
      // Simulate connecting to camera
      navigator.mediaDevices.getUserMedia({ video: true })
        .then(stream => {
          if (videoRef.current) {
            videoRef.current.srcObject = stream;
          }
        })
        .catch(err => console.error("Camera error", err));

      // Simulate MediaPipe Analysis Loop
      interval = setInterval(() => {
        // Mock angle fluctuation (simulating a leg lift)
        setCurrentAngle(prev => {
          const change = Math.floor(Math.random() * 5);
          const increasing = Math.floor(Date.now() / 2000) % 2 === 0;
          let next = increasing ? prev + change : prev - change;
          if (next > 130) next = 130;
          if (next < 0) next = 0;
          return next;
        });

        // Mock Rep Counting Logic
        if (Math.random() > 0.98) {
             setReps(r => {
                 const newReps = r + 1;
                 if (newReps >= (activeExercise?.targetReps || 10)) {
                     endSession();
                 }
                 return newReps;
             });
             setFeedback("Good form! Keep going.");
        } else if (Math.random() > 0.95) {
             setFeedback("Try to extend fully.");
        }
      }, 100);
    } else {
        // Cleanup camera
        if (videoRef.current?.srcObject) {
            const tracks = (videoRef.current.srcObject as MediaStream).getTracks();
            tracks.forEach(track => track.stop());
        }
    }

    return () => clearInterval(interval);
  }, [isExercising, sessionComplete, activeExercise]);

  const startSession = (exercise: Exercise) => {
    setActiveExercise(exercise);
    setIsExercising(true);
    setSessionComplete(false);
    setReps(0);
  };

  const endSession = () => {
    setIsExercising(false);
    setSessionComplete(true);
  };

  const saveLog = () => {
    // In a real app, this would push to Firebase
    alert("Session logged successfully!");
    setSessionComplete(false);
    setActiveExercise(null);
  };

  // 1. Exercise List View
  if (!activeExercise && !sessionComplete) {
    return (
      <div className="min-h-screen bg-slate-50 flex flex-col">
        <header className="bg-white p-4 shadow-sm flex items-center gap-3 sticky top-0 z-20">
          <button onClick={onBack} className="text-slate-500">
            <ArrowLeft />
          </button>
          <h1 className="font-bold text-lg text-slate-800">My Care Plan</h1>
        </header>

        <main className="flex-1 p-4 space-y-4">
          <div className="bg-blue-600 rounded-xl p-5 text-white shadow-lg shadow-blue-200">
             <p className="text-blue-100 text-sm mb-1">Today's Goal</p>
             <h2 className="text-2xl font-bold">Complete 2 Sessions</h2>
             <div className="mt-4 flex gap-2">
                <div className="h-2 flex-1 bg-blue-500 rounded-full overflow-hidden">
                    <div className="h-full bg-white w-1/2"></div>
                </div>
                <span className="text-xs font-medium">50%</span>
             </div>
          </div>

          <h3 className="font-semibold text-slate-700 mt-2">Assigned Exercises</h3>
          <div className="space-y-3">
            {patient.prescribedExercises.map(ex => (
              <div key={ex.id} onClick={() => startSession(ex)} className="bg-white p-4 rounded-xl border border-slate-100 shadow-sm flex items-center justify-between active:scale-95 transition-transform cursor-pointer">
                 <div className="flex items-center gap-4">
                    <div className="w-12 h-12 rounded-full bg-blue-50 flex items-center justify-center text-blue-600">
                        <Play size={20} fill="currentColor" />
                    </div>
                    <div>
                        <h4 className="font-bold text-slate-800">{ex.name}</h4>
                        <p className="text-xs text-slate-500">{ex.targetReps} Reps • {ex.targetRom}° Target</p>
                    </div>
                 </div>
                 <ChevronRight className="text-slate-300" />
              </div>
            ))}
          </div>
        </main>
      </div>
    );
  }

  // 2. Completion & Logging View
  if (sessionComplete) {
    return (
        <div className="min-h-screen bg-white flex flex-col p-6 animate-in fade-in slide-in-from-bottom-8">
            <div className="flex-1 flex flex-col items-center justify-center text-center">
                <div className="w-20 h-20 bg-green-100 text-green-600 rounded-full flex items-center justify-center mb-6">
                    <CheckCircle2 size={40} />
                </div>
                <h2 className="text-2xl font-bold text-slate-900">Great Job, {patient.name.split(' ')[0]}!</h2>
                <p className="text-slate-500 mt-2">You completed {reps} reps of {activeExercise?.name}.</p>

                <div className="w-full mt-12 bg-slate-50 p-6 rounded-2xl">
                    <label className="block text-left text-sm font-semibold text-slate-700 mb-4">How was your pain level?</label>
                    <div className="flex justify-between items-center mb-2 px-1">
                        <span className="text-xs text-slate-500">No Pain</span>
                        <span className="text-xs text-slate-500">Severe</span>
                    </div>
                    <input 
                        type="range" 
                        min="0" max="10" 
                        value={painScore} 
                        onChange={(e) => setPainScore(parseInt(e.target.value))}
                        className="w-full h-2 bg-slate-200 rounded-lg appearance-none cursor-pointer accent-blue-600"
                    />
                    <div className="text-center mt-4 font-bold text-3xl text-blue-600">{painScore}</div>
                </div>
            </div>
            <button onClick={saveLog} className="w-full py-4 bg-slate-900 text-white rounded-xl font-bold text-lg shadow-xl shadow-slate-200 hover:bg-slate-800 transition-all">
                Save & Finish
            </button>
        </div>
    );
  }

  // 3. Active Exercise (Vision) View
  return (
    <div className="fixed inset-0 bg-black flex flex-col">
       {/* Camera Layer */}
       <div className="relative flex-1 bg-slate-900 overflow-hidden">
          <video 
            ref={videoRef} 
            autoPlay 
            playsInline 
            muted 
            className="absolute inset-0 w-full h-full object-cover opacity-80"
          />

          {/* Simulation Overlay - Skeleton */}
          <div className="absolute inset-0 flex items-center justify-center pointer-events-none">
             <div className="relative w-64 h-96 border-2 border-white/20 rounded-lg flex items-center justify-center">
                {/* Simulated Joint Dots */}
                <div className="absolute top-1/4 left-1/2 w-4 h-4 bg-blue-500 rounded-full shadow-[0_0_15px_rgba(59,130,246,0.8)]"></div>
                <div className="absolute top-1/2 left-1/2 w-4 h-4 bg-blue-500 rounded-full shadow-[0_0_15px_rgba(59,130,246,0.8)]"></div>

                {/* Dynamic limb simulation based on state */}
                <div 
                  className="absolute bottom-1/4 left-1/2 w-32 h-2 bg-blue-400 origin-left rounded-full"
                  style={{ transform: `rotate(-${currentAngle}deg)` }}
                ></div>

                {/* Angle Readout */}
                <div className="absolute top-1/2 left-20 text-white font-mono text-xs bg-black/50 px-2 py-1 rounded">
                    {currentAngle}°
                </div>
             </div>
          </div>

          {/* HUD */}
          <div className="absolute top-0 left-0 right-0 p-6 pt-12 bg-gradient-to-b from-black/80 to-transparent text-white">
             <div className="flex justify-between items-start">
                 <div>
                     <h3 className="font-bold text-lg">{activeExercise?.name}</h3>
                     <p className="text-blue-200 text-sm flex items-center gap-2">
                        <RefreshCw size={14} /> Tracking Active
                     </p>
                 </div>
                 <div className="text-right">
                    <div className="text-4xl font-bold">{reps} <span className="text-base font-normal text-white/60">/ {activeExercise?.targetReps}</span></div>
                    <div className="text-xs text-white/60 uppercase tracking-wider">Reps</div>
                 </div>
             </div>
          </div>
       </div>

       {/* Bottom Control / Feedback */}
       <div className="bg-slate-900 p-6 pb-10 rounded-t-3xl -mt-6 relative z-10 border-t border-slate-800">
           <div className="flex items-center gap-4 mb-6">
                <div className={`p-3 rounded-full ${feedback.includes('Good') ? 'bg-green-500/20 text-green-400' : 'bg-amber-500/20 text-amber-400'}`}>
                    {feedback.includes('Good') ? <CheckCircle2 /> : <AlertCircle />}
                </div>
                <p className="text-white font-medium text-lg leading-tight">
                    {feedback}
                </p>
           </div>

           <button 
             onClick={endSession}
             className="w-full py-4 bg-white/10 text-white rounded-xl font-semibold border border-white/10 hover:bg-white/20 transition-all"
           >
             End Session Early
           </button>
       </div>
    </div>
  );
};

import React, { useState } from 'react';
import { UserRole } from './types';
import { MOCK_PATIENT } from './constants';
import { PhysioDashboard } from './components/PhysioDashboard';
import { PatientApp } from './components/PatientApp';
import { Stethoscope, User, ShieldCheck } from 'lucide-react';

const App: React.FC = () => {
  const [currentRole, setCurrentRole] = useState<UserRole>(UserRole.NONE);

  const reset = () => setCurrentRole(UserRole.NONE);

  if (currentRole === UserRole.PHYSIO) {
    return <PhysioDashboard patient={MOCK_PATIENT} onBack={reset} />;
  }

  if (currentRole === UserRole.PATIENT) {
    return <PatientApp patient={MOCK_PATIENT} onBack={reset} />;
  }

  // Landing / Role Selection Screen
  return (
    <div className="min-h-screen bg-slate-50 flex items-center justify-center p-4">
      <div className="max-w-md w-full">
        <div className="text-center mb-10">
          <div className="w-16 h-16 bg-blue-600 rounded-2xl mx-auto flex items-center justify-center text-white shadow-xl shadow-blue-200 mb-4">
            <ShieldCheck size={32} />
          </div>
          <h1 className="text-3xl font-bold text-slate-900 tracking-tight">PhysioAI Monitor</h1>
          <p className="text-slate-500 mt-2">Intelligent recovery tracking & sensorless motion analysis.</p>
        </div>

        <div className="space-y-4">
          <button 
            onClick={() => setCurrentRole(UserRole.PHYSIO)}
