                 </div>
                 <ChevronRight className="text-slate-300" />
              </div>
            ))}
          </div>

          <div className="pt-8 pb-4">
             <button onClick={handleEndJourney} className="w-full flex items-center justify-center gap-2 py-3 border-2 border-red-100 text-red-600 rounded-xl font-semibold hover:bg-red-50 transition-colors">
                <Mail size={18} />
                <Lock size={14} />
                Close Case & Email Report
             </button>
             <p className="text-center text-xs text-slate-400 mt-2">This will erase your temporary access key.</p>
          </div>
        </main>
      </div>
    );
  }

  // 2. Completion & Logging View (Unchanged logic, just keeping structure)
  if (sessionComplete) {
    return (
        <div className="min-h-screen bg-white flex flex-col p-6 animate-in fade-in slide-in-from-bottom-8">
            <div className="flex-1 flex flex-col items-center justify-center text-center">
                <div className="w-20 h-20 bg-green-100 text-green-600 rounded-full flex items-center justify-center mb-6">
                    <CheckCircle2 size={40} />
                </div>
                <h2 className="text-2xl font-bold text-slate-900">Great Job, {patient.name.split(' ')[0]}!</h2>
                <p className="text-slate-500 mt-2">You completed {reps} reps of {activeExercise?.name}.</p>

                <div className="w-full mt-12 bg-slate-50 p-6 rounded-2xl">
                    <label className="block text-left text-sm font-semibold text-slate-700 mb-4">How was your pain level?</label>
                    <div className="flex justify-between items-center mb-2 px-1">
                        <span className="text-xs text-slate-500">No Pain</span>
                        <span className="text-xs text-slate-500">Severe</span>
                    </div>
                    <input 
                        type="range" 
                        min="0" max="10" 
                        value={painScore} 
                        onChange={(e) => setPainScore(parseInt(e.target.value))}
                        className="w-full h-2 bg-slate-200 rounded-lg appearance-none cursor-pointer accent-blue-600"
                    />
                    <div className="text-center mt-4 font-bold text-3xl text-blue-600">{painScore}</div>
                </div>
            </div>
            <button onClick={saveLog} className="w-full py-4 bg-slate-900 text-white rounded-xl font-bold text-lg shadow-xl shadow-slate-200 hover:bg-slate-800 transition-all">
                Save & Finish
            </button>
        </div>
    );
  }

  // 3. Active Exercise (Vision) View (Updated for Wrist visualization concept)
  return (
    <div className="fixed inset-0 bg-black flex flex-col">
       <div className="relative flex-1 bg-slate-900 overflow-hidden">
          <video 
            ref={videoRef} 
            autoPlay 
            playsInline 
            muted 
            className="absolute inset-0 w-full h-full object-cover opacity-80"
          />

          <div className="absolute inset-0 flex items-center justify-center pointer-events-none">
             <div className="relative w-64 h-64 border-2 border-white/20 rounded-full flex items-center justify-center">
                {/* Hand/Wrist Sim */}
                <div className="absolute top-1/2 left-1/2 w-4 h-4 bg-blue-500 rounded-full shadow-[0_0_15px_rgba(59,130,246,0.8)] z-10"></div>
                <div 
                  className="absolute top-1/2 left-1/2 w-24 h-2 bg-blue-400 origin-left rounded-full"
                  style={{ transform: `rotate(-${currentAngle + 90}deg)` }}
                ></div>
                <div className="absolute bottom-10 text-white font-mono text-xl font-bold bg-black/50 px-3 py-1 rounded">
                    {currentAngle}°
                </div>
             </div>
          </div>

          <div className="absolute top-0 left-0 right-0 p-6 pt-12 bg-gradient-to-b from-black/80 to-transparent text-white">
             <div className="flex justify-between items-start">
                 <div>
                     <h3 className="font-bold text-lg">{activeExercise?.name}</h3>
                     <p className="text-blue-200 text-sm flex items-center gap-2">
                        <RefreshCw size={14} /> Hand Tracking Active
