    pain: log.painScore,
    benchmark: patient.benchmarkRom[Math.min(index, patient.benchmarkRom.length - 1)] || 0
  }));

  const handleAIAnalysis = async () => {
    setIsAnalyzing(true);
    try {
      const result = await analyzePatientProgress(patient);
      setAnalysis(result);
    } catch (e) {
      setAnalysis("Failed to connect to AI service.");
    } finally {
      setIsAnalyzing(false);
    }
  };

