        email: details.email,
        physioName: details.physioName
    };
    setCurrentPatient(updatedPatient);
    setCurrentRole(role);
    setIsRegistering(false);
  };

  if (isRegistering) {
      return <RegistrationForm onRegister={handleRegistration} onCancel={reset} />;
  }

  if (currentRole === UserRole.PHYSIO) {
    return <PhysioDashboard patients={MOCK_PATIENTS} onBack={reset} />;
  }

  if (currentRole === UserRole.PATIENT) {
    return <PatientApp patient={currentPatient} onBack={reset} />;
