                <h1 className="text-2xl font-bold text-slate-800">{patient.name}</h1>
                <p className="text-sm text-slate-500">Age: {patient.age} • Email: {patient.email}</p>
            </div>
            <div className="flex items-center gap-4">
                <div className="text-right">
                    <p className="text-sm font-semibold text-slate-800">{patient.physioName}</p>
                    <div className="flex items-center justify-end gap-1 text-xs text-blue-600 font-medium">
                        <BadgeCheck size={14} /> Verified Physio
                    </div>
                </div>
                <div className="w-10 h-10 bg-slate-200 rounded-full flex items-center justify-center text-slate-500 font-bold border-2 border-white shadow-sm">
