    e.preventDefault();
    setError('');
    setIsVerifying(true);

    // Simulate network delay for verification
    setTimeout(() => {
        const physio = VERIFIED_PHYSIOS[licenseId];
        if (physio) {
            onLogin(physio);
        } else {
            setError('License ID not found in the national registry.');
            setIsVerifying(false);
        }
    }, 800);
  };

  return (
    <div className="min-h-screen bg-slate-50 flex items-center justify-center p-4">
      <div className="max-w-md w-full bg-white rounded-2xl shadow-xl p-8 border border-slate-100">
        <div className="text-center mb-8">
           <div className="w-16 h-16 bg-blue-600 rounded-2xl mx-auto flex items-center justify-center text-white shadow-lg shadow-blue-200 mb-4">
              <Stethoscope size={32} />
           </div>
           <h2 className="text-2xl font-bold text-slate-900">Clinician Portal</h2>
           <p className="text-sm text-slate-500 mt-2">Secure access for verified physiotherapists.</p>
        </div>

        <form onSubmit={handleLogin} className="space-y-6">
          <div className="bg-blue-50 p-4 rounded-xl border border-blue-100">
            <label className="block text-xs font-bold text-blue-800 uppercase tracking-wide mb-2">Medical License ID</label>
            <div className="relative">
                <Lock className="absolute left-3 top-1/2 -translate-y-1/2 text-blue-400" size={18} />
                <input 
                required
                type="text" 
                className="w-full pl-10 pr-4 py-3 rounded-lg border-2 border-blue-200 focus:border-blue-500 focus:ring-0 outline-none bg-white font-mono text-slate-800 placeholder-slate-400"
                placeholder="e.g. PT-88321"
                value={licenseId}
                onChange={e => setLicenseId(e.target.value)}
                />
            </div>
            <p className="text-[10px] text-blue-400 mt-2 text-right">Demo ID: PT-88321</p>
          </div>

          {error && (
              <div className="flex items-center gap-2 text-red-600 bg-red-50 p-3 rounded-lg text-sm">
                  <AlertCircle size={16} />
                  <span>{error}</span>
              </div>
          )}

          <div className="pt-2">
            <button 
                type="submit" 
                disabled={isVerifying}
                className="w-full bg-slate-900 hover:bg-slate-800 text-white font-bold py-3.5 rounded-xl transition-all shadow-lg flex items-center justify-center gap-2 disabled:opacity-70 disabled:cursor-not-allowed"
            >
                {isVerifying ? 'Verifying Credentials...' : 'Verify & Access Dashboard'}
                {!isVerifying && <ArrowRight size={18} />}
            </button>
            <button type="button" onClick={onCancel} className="w-full mt-3 text-slate-500 hover:text-slate-800 text-sm font-medium py-2">
                Back to Home
            </button>
          </div>
        </form>

        <div className="mt-8 border-t border-slate-100 pt-6 flex items-center justify-center gap-2 text-xs text-slate-400">
            <ShieldCheck size={14} className="text-green-500" />
            <span>Protected by MedSafe Auth</span>
        </div>
      </div>
    </div>
  );
};

import React, { useState } from 'react';
import { LineChart, Line, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, Legend } from 'recharts';
import { Activity, AlertTriangle, FileText, ChevronLeft, Bot, BadgeCheck, Users, BrainCircuit, ArrowLeft, Send, Sparkles } from 'lucide-react';
import { Patient } from '../types';
import { analyzePatientProgress, getRecoveryPrediction } from '../services/geminiService';
import { INJURY_LIBRARY } from '../constants';
import ReactMarkdown from 'react-markdown';

interface PhysioDashboardProps {
  patients: Patient[];
  onBack: () => void;
  currentPhysio?: { name: string; id: string };
}

export const PhysioDashboard: React.FC<PhysioDashboardProps> = ({ patients, onBack, currentPhysio }) => {
  const [selectedPatientId, setSelectedPatientId] = useState<string>(patients[0].id);
  const [analysis, setAnalysis] = useState<string | null>(null);
  const [isAnalyzing, setIsAnalyzing] = useState(false);

  // Bot State
  const [botInjury, setBotInjury] = useState<string>(patients[0].injuryType);
  const [botPrediction, setBotPrediction] = useState<string | null>(null);
  const [isPredicting, setIsPredicting] = useState(false);

  const patient = patients.find(p => p.id === selectedPatientId) || patients[0];

  const chartData = patient.logs.map((log, index) => ({
    date: log.date.split('-').slice(1).join('/'), // MM/DD
    rom: log.maxRom,
    pain: log.painScore,
    benchmark: patient.benchmarkRom[Math.min(index, patient.benchmarkRom.length - 1)] || 0
  }));

  const handleAIAnalysis = async () => {
    setIsAnalyzing(true);
    try {
      const result = await analyzePatientProgress(patient);
      setAnalysis(result);
    } catch (e) {
      setAnalysis("Failed to connect to AI service.");
    } finally {
      setIsAnalyzing(false);
    }
  };

  const handlePrediction = async () => {
      if (!botInjury) return;

      setIsPredicting(true);
      const injuryProfile = INJURY_LIBRARY[botInjury];

      if (!injuryProfile) {
          setBotPrediction("Error: Selected injury protocol configuration not found.");
          setIsPredicting(false);
          return;
      }

      try {
          const result = await getRecoveryPrediction(patient, injuryProfile);
          setBotPrediction(result);
      } catch (e) {
          setBotPrediction("Bot unavailable. Please check your API connection.");
      } finally {
          setIsPredicting(false);
      }
  };

  return (
    <div className="flex h-screen bg-slate-50 overflow-hidden">

      {/* Sidebar - Patient List */}
      <aside className="w-72 bg-white border-r border-slate-200 flex flex-col z-20">
        <div className="p-4 border-b border-slate-100 flex items-center gap-3">
            <button 
                onClick={onBack} 
                className="p-2 -ml-2 hover:bg-slate-100 rounded-full text-slate-600 transition-colors"
                title="Go Back"
            >
                <ArrowLeft size={20} />
            </button>
            <h2 className="text-lg font-bold text-slate-800 flex items-center gap-2">
                <Users size={20} className="text-blue-600" />
                My Patients
            </h2>
        </div>
        <div className="flex-1 overflow-y-auto">
            {patients.map(p => (
                <button
                    key={p.id}
                    onClick={() => {
                        setSelectedPatientId(p.id);
                        setAnalysis(null);
                        setBotPrediction(null);
                        setBotInjury(p.injuryType);
                    }}
                    className={`w-full text-left p-4 border-b border-slate-50 hover:bg-slate-50 transition-colors group ${selectedPatientId === p.id ? 'bg-blue-50 border-l-4 border-l-blue-600' : ''}`}
                >
                    <div className="flex justify-between items-start">
                        <p className={`font-semibold ${selectedPatientId === p.id ? 'text-blue-700' : 'text-slate-700'}`}>{p.name}</p>
                        {selectedPatientId === p.id && <ChevronLeft className="text-blue-600 rotate-180" size={16} />}
                    </div>
                    <p className="text-xs text-slate-500 truncate">{p.injury}</p>
                    <div className={`mt-2 text-xs inline-block px-2 py-0.5 rounded-full ${p.status === 'On Track' ? 'bg-green-100 text-green-700' : 'bg-red-100 text-red-700'}`}>
                        {p.status}
                    </div>
                </button>
            ))}
        </div>
      </aside>

      {/* Main Content */}
      <div className="flex-1 flex flex-col overflow-hidden">
        {/* Header */}
        <header className="bg-white border-b border-slate-200 px-6 py-4 flex items-center justify-between shadow-sm z-10">
            <div>
                <h1 className="text-2xl font-bold text-slate-800">{patient.name}</h1>
                <p className="text-sm text-slate-500">Age: {patient.age} • Email: {patient.email}</p>
            </div>
            <div className="flex items-center gap-4">
                <div className="text-right">
                    <p className="text-sm font-semibold text-slate-800">{currentPhysio?.name || "Clinician View"}</p>
                    <div className="flex items-center justify-end gap-1.5 text-xs text-white font-medium bg-green-600 px-3 py-1 rounded-full shadow-sm shadow-green-200">
                        <BadgeCheck size={14} fill="currentColor" className="text-white" /> 
                        <span>Verified Credentials</span>
                    </div>
                </div>
                <div className="w-10 h-10 bg-slate-800 rounded-full flex items-center justify-center text-white font-bold border-2 border-slate-200 shadow-sm">
                    {currentPhysio?.name.split(' ').map(n => n[0]).join('').slice(0, 2) || "MD"}
                </div>
            </div>
        </header>

        <main className="flex-1 overflow-auto p-6 w-full bg-slate-50/50">
            <div className="max-w-7xl mx-auto grid grid-cols-1 lg:grid-cols-3 gap-6">

            {/* Main Chart Section */}
            <div className="lg:col-span-2 space-y-6">

                {/* Chart Card */}
                <div className="bg-white p-6 rounded-xl shadow-sm border border-slate-100">
                    <div className="flex items-center justify-between mb-6">
                        <h3 className="text-lg font-semibold text-slate-800 flex items-center gap-2">
                        <Activity className="text-blue-500" size={20} />
                        ROM Recovery Curve
                        </h3>
                    </div>
                    <div className="h-[300px] w-full">
                        <ResponsiveContainer width="100%" height="100%">
                        <LineChart data={chartData} margin={{ top: 5, right: 30, left: 20, bottom: 5 }}>
                            <CartesianGrid strokeDasharray="3 3" stroke="#f1f5f9" />
                            <XAxis dataKey="date" stroke="#94a3b8" fontSize={12} tickLine={false} />
                            <YAxis stroke="#94a3b8" fontSize={12} tickLine={false} label={{ value: 'Degrees (°)', angle: -90, position: 'insideLeft', style: { fill: '#94a3b8' } }} />
                            <Tooltip 
                            contentStyle={{ backgroundColor: '#fff', borderRadius: '8px', border: '1px solid #e2e8f0', boxShadow: '0 4px 6px -1px rgb(0 0 0 / 0.1)' }}
                            />
                            <Legend />
                            <Line type="monotone" dataKey="rom" name="Patient ROM" stroke="#3b82f6" strokeWidth={3} dot={{ r: 4 }} activeDot={{ r: 8 }} />
                            <Line type="monotone" dataKey="benchmark" name="Protocol Target" stroke="#cbd5e1" strokeWidth={2} strokeDasharray="5 5" dot={false} />
                        </LineChart>
                        </ResponsiveContainer>
                    </div>
                </div>

                {/* Dark Mode Injury Predictor Bot */}
                <div className="bg-slate-900 rounded-xl shadow-lg border border-slate-800 overflow-hidden flex flex-col min-h-[300px]">
                    {/* Bot Header */}
                    <div className="p-4 bg-slate-950/50 border-b border-slate-800 flex items-center justify-between">
                        <h3 className="font-semibold text-slate-100 flex items-center gap-2">
                            <BrainCircuit className="text-purple-400" size={20} />
                            Injury Predictor Bot
                        </h3>
                        <span className="text-xs bg-purple-900/50 text-purple-300 border border-purple-700/50 px-2 py-0.5 rounded-full">AI Active</span>
                    </div>

                    {/* Chat Interface */}
                    <div className="p-6 space-y-6 flex-1 bg-gradient-to-b from-slate-900 to-slate-950">

                        {/* Bot Prompt */}
                        <div className="flex gap-4 animate-in slide-in-from-left-4 fade-in duration-500">
                            <div className="w-10 h-10 rounded-full bg-purple-900/30 border border-purple-700/50 flex items-center justify-center shrink-0">
                                <Bot size={20} className="text-purple-300" />
                            </div>
                            <div className="bg-slate-800 p-4 rounded-r-2xl rounded-bl-2xl text-slate-200 text-sm border border-slate-700 shadow-sm max-w-[85%]">
                                <p>Hello Physio. To begin the trajectory analysis, please confirm the injury protocol you wish to track for <strong>{patient.name}</strong>.</p>
                            </div>
                        </div>

                        {/* User Selection (Physio) */}
                        <div className="flex justify-end gap-4 animate-in slide-in-from-right-4 fade-in duration-500 delay-100">
                            <div className="flex flex-col items-end gap-2 max-w-[85%]">
                                <div className="bg-blue-600 p-2 pl-3 pr-2 rounded-l-2xl rounded-br-2xl text-white text-sm shadow-md flex items-center gap-3">
                                    <span className="text-blue-100 text-xs uppercase font-bold tracking-wider">Protocol:</span>
                                    <select 
                                        value={botInjury}
                                        onChange={(e) => setBotInjury(e.target.value)}
                                        className="bg-blue-700/50 hover:bg-blue-700 transition-colors border border-blue-400/30 text-white text-sm rounded-lg px-2 py-1.5 focus:ring-2 focus:ring-white/50 cursor-pointer outline-none [&>option]:text-slate-900 [&>option]:bg-white"
                                    >
                                        {Object.values(INJURY_LIBRARY).map(inj => (
                                            <option key={inj.id} value={inj.id}>{inj.name}</option>
                                        ))}
                                    </select>
                                    <button 
                                        onClick={handlePrediction}
                                        disabled={isPredicting}
                                        className="bg-white text-blue-600 p-2 rounded-full hover:bg-blue-50 transition-colors disabled:opacity-50 disabled:cursor-not-allowed shadow-sm"
                                        title="Run Prediction"
                                    >
                                        {isPredicting ? <div className="w-3.5 h-3.5 border-2 border-blue-600 border-t-transparent rounded-full animate-spin"></div> : <Send size={14} fill="currentColor" />}
                                    </button>
                                </div>
                                <span className="text-[10px] text-slate-500 pr-1">Physio Selection</span>
                            </div>
                            <div className="w-10 h-10 rounded-full bg-slate-800 flex items-center justify-center shrink-0 text-slate-400 font-bold border border-slate-700">
                                {currentPhysio?.name.split(' ').map(n => n[0]).join('').slice(0, 2) || "MD"}
                            </div>
                        </div>

                        {/* Bot Response (High Contrast) */}
                        {isPredicting && (
                             <div className="flex gap-4 animate-pulse">
                                <div className="w-10 h-10 rounded-full bg-purple-900/30 border border-purple-700/50 flex items-center justify-center shrink-0">
                                    <Bot size={20} className="text-purple-300" />
                                </div>
                                <div className="bg-slate-800 p-3 rounded-r-2xl rounded-bl-2xl text-slate-400 text-sm italic border border-slate-700">
                                    Analyzing clinical logs against protocol milestones...
                                </div>
                             </div>
                        )}

                        {botPrediction && !isPredicting && (
                            <div className="flex gap-4 animate-in fade-in slide-in-from-left-2 duration-500">
                                <div className="w-10 h-10 rounded-full bg-purple-900/30 border border-purple-700/50 flex items-center justify-center shrink-0">
                                    <Bot size={20} className="text-purple-300" />
                                </div>
                                <div className="space-y-2 max-w-[90%]">
                                    <div className="bg-black text-white p-5 rounded-xl border border-slate-700 shadow-xl ring-1 ring-white/10">
                                        <div className="prose prose-invert prose-sm max-w-none leading-relaxed">
                                            <ReactMarkdown>{botPrediction}</ReactMarkdown>
                                        </div>
                                    </div>
                                    <div className="flex items-center gap-2 pl-2">
                                        <Sparkles size={12} className="text-purple-400" />
                                        <p className="text-[10px] text-slate-500">Generated by Gemini 2.5 Flash • Medical Assistant Mode</p>
                                    </div>
                                </div>
                            </div>
                        )}
                    </div>
                </div>
            </div>

            {/* Right Sidebar / Logs */}
            <div className="space-y-6">
                {/* Regular AI Summary */}
                <div className="bg-gradient-to-br from-indigo-600 to-purple-700 rounded-xl p-6 text-white shadow-lg relative overflow-hidden group">
                    <div className="absolute top-0 right-0 p-4 opacity-10 group-hover:opacity-20 transition-opacity duration-500">
                        <Bot size={120} />
                    </div>
                    <div className="relative z-10">
                        <div className="flex items-start justify-between mb-4">
                            <div>
                                <h3 className="text-lg font-bold flex items-center gap-2">
                                    Clinical Notes
                                </h3>
                                <p className="text-indigo-100 text-xs mt-1">General progress summary</p>
                            </div>
                        </div>

                        {!analysis ? (
                            <button 
                            onClick={handleAIAnalysis}
                            disabled={isAnalyzing}
                            className="w-full py-3 bg-white text-indigo-700 rounded-lg font-semibold hover:bg-indigo-50 transition-colors disabled:opacity-70 disabled:cursor-not-allowed text-sm shadow-sm"
                            >
                            {isAnalyzing ? 'Analyzing Logs...' : 'Generate Summary'}
                            </button>
                        ) : (
                            <div className="bg-white/10 backdrop-blur-md rounded-lg p-4 text-xs animate-in fade-in border border-white/20">
                            <div className="flex justify-between items-center mb-2 border-b border-white/20 pb-2">
                                <span className="font-semibold text-indigo-100">AI Report</span>
                                <button onClick={() => setAnalysis(null)} className="hover:text-white text-indigo-200 transition-colors">Reset</button>
                            </div>
                            <div className="prose prose-invert prose-sm max-h-[300px] overflow-y-auto custom-scrollbar">
                                <ReactMarkdown>{analysis}</ReactMarkdown>
                            </div>
                            </div>
                        )}
                    </div>
                </div>

                <div className="bg-white p-6 rounded-xl shadow-sm border border-slate-100">
                <h3 className="text-lg font-semibold text-slate-800 mb-4 flex items-center gap-2">
                    <FileText className="text-slate-400" size={20} />
                    Latest Logs
                </h3>
