  const handleSendReport = () => {
      if (!reportText.trim()) return;
      setIsSendingReport(true);

      // Simulate API call
      setTimeout(() => {
          const newReport = {
              id: `r${Date.now()}`,
              date: new Date().toISOString().split('T')[0],
