              physioName: currentPhysio?.name || 'Physiotherapist'
          };

          setActivePatient({
              ...activePatient,
              weeklyReports: [newReport, ...activePatient.weeklyReports]
          });

          setReportText('');
          setIsSendingReport(false);
          alert("Report sent to patient's desk!");
      }, 1000);
  };

