                                ) : voiceAnalysis ? (
                                    <div className="text-xs text-left bg-purple-50 p-3 rounded-lg border border-purple-100 text-purple-900">
                                        <div className="flex items-center gap-1 font-bold mb-1 text-purple-700">
                                            <Sparkles size={10} /> AI Insight:
                                        </div>
                                        {voiceAnalysis}
