                                ) : null}
                            </div>
                        )}
                    </div>
                </div>
            </div>
            <button onClick={saveLog} className="w-full py-4 bg-slate-900 text-white rounded-xl font-bold text-lg shadow-xl shadow-slate-200 hover:bg-slate-800 transition-all mb-4">
                Save & Finish
            </button>
        </div>
