      onAddPatient(newPatient);
      setSelectedPatientId(newPatient.id);
      setIsAddModalOpen(false);

      // Reset State
      setAddStep(1);
      setNewPatientData({ phone: '', otp: '', name: '', age: '', injuryType: Object.keys(INJURY_LIBRARY)[0] });
      setOtpSent(false);
      setOtpVerified(false);
