import React, { useState, useEffect } from 'react';
import { UserRole, Patient, DailyLog } from './types';
import { MOCK_PATIENTS } from './constants';
import { PhysioDashboard } from './components/PhysioDashboard';
import { PatientApp } from './components/PatientApp';
import { RegistrationForm } from './components/RegistrationForm';
import { PhysioLogin } from './components/PhysioLogin';
import { Activity, ShieldCheck, ChevronRight, Stethoscope, User } from 'lucide-react';
import { generateDischargeReport } from './services/geminiService';

const STORAGE_KEY = 'physio_app_data_v1';

const App: React.FC = () => {
  const [currentRole, setCurrentRole] = useState<UserRole>(UserRole.NONE);
  const [isRegistering, setIsRegistering] = useState(false);
  const [isPhysioLoggingIn, setIsPhysioLoggingIn] = useState(false);

  const [patientsList, setPatientsList] = useState<Patient[]>(() => {
      try {
          const saved = localStorage.getItem(STORAGE_KEY);
          if (saved) return JSON.parse(saved);
      } catch (e) { console.error(e); }
      return MOCK_PATIENTS;
  });

  useEffect(() => {
      localStorage.setItem(STORAGE_KEY, JSON.stringify(patientsList));
  }, [patientsList]);

  const [currentPatient, setCurrentPatient] = useState<Patient>(patientsList[0]);
  const [currentPhysio, setCurrentPhysio] = useState<{name: string, id: string} | undefined>(undefined);

  useEffect(() => {
      const freshData = patientsList.find(p => p.id === currentPatient.id);
      if (freshData) setCurrentPatient(freshData);
  }, [patientsList, currentPatient.id]);

  const reset = () => {
    setCurrentRole(UserRole.NONE);
    setIsRegistering(false);
    setIsPhysioLoggingIn(false);
    setCurrentPhysio(undefined);
  };

  const handleRegistration = (role: UserRole, details: any) => {
    const existingPatient = patientsList.find(p => p.email.toLowerCase() === details.email.toLowerCase());
    if (existingPatient) {
        setCurrentPatient(existingPatient);
    } else {
        const newPatient: Patient = {
            ...MOCK_PATIENTS[0],
            id: `p${Date.now()}`,
            name: details.name,
            age: parseInt(details.age) || 25,
            email: details.email,
            physioName: details.physioName,
            logs: [],
            weeklyReports: []
        };
        setPatientsList(prev => [newPatient, ...prev]);
        setCurrentPatient(newPatient);
    }
    setCurrentRole(role);
    setIsRegistering(false);
  };

  const handlePhysioLogin = (physio: {name: string, id: string}) => {
      setCurrentPhysio(physio);
      setCurrentRole(UserRole.PHYSIO);
      setIsPhysioLoggingIn(false);
  };

  const updatePatientData = (updatedPatient: Patient) => {
      setPatientsList(prev => prev.map(p => p.id === updatedPatient.id ? updatedPatient : p));
  };

  const handleLogEntry = (log: DailyLog) => {
    const updatedPatient = { ...currentPatient, logs: [...currentPatient.logs, log] };
    updatePatientData(updatedPatient);
  };

  const handlePatientUpdate = (updatedPatient: Patient) => updatePatientData(updatedPatient);
  const handleAddPatient = (newPatient: Patient) => setPatientsList(prev => [newPatient, ...prev]);

  const handleDischarge = async () => {
      const report = await generateDischargeReport(currentPatient);
      alert(`SYSTEM: Report emailed to ${currentPatient.email}`);
      const resetPatient = { ...currentPatient, logs: [], weeklyReports: [], status: 'On Track' as const };
      updatePatientData(resetPatient);
      reset();
  };

  if (isRegistering) return <RegistrationForm onRegister={handleRegistration} onCancel={reset} />;
  if (isPhysioLoggingIn) return <PhysioLogin onLogin={handlePhysioLogin} onCancel={reset} />;

  if (currentRole === UserRole.PHYSIO) return (
      <PhysioDashboard 
          patients={patientsList} 
          onBack={reset} 
          currentPhysio={currentPhysio} 
          onPatientUpdate={handlePatientUpdate}
          onAddPatient={handleAddPatient}
      />
  );

  if (currentRole === UserRole.PATIENT) return <PatientApp patient={currentPatient} onBack={reset} onLogEntry={handleLogEntry} onDischarge={handleDischarge} />;

  return (
    <div className="min-h-screen bg-[#f8fafc] flex flex-col items-center justify-center p-6 relative overflow-hidden">
      {/* Decorative Blur Elements */}
      <div className="absolute -top-24 -left-24 w-96 h-96 bg-blue-100 rounded-full blur-3xl opacity-50" />
      <div className="absolute -bottom-24 -right-24 w-96 h-96 bg-indigo-100 rounded-full blur-3xl opacity-50" />

      <div className="max-w-xl w-full relative z-10">
        <div className="text-center mb-12">
          <div className="inline-flex items-center gap-2 px-4 py-2 bg-white rounded-full border border-slate-200 shadow-sm text-xs font-bold text-brand-600 uppercase tracking-widest mb-6">
            <ShieldCheck size={14} /> Medical Grade Tracking
          </div>
          <h1 className="text-5xl font-black text-slate-900 tracking-tighter mb-4">
            Physio<span className="text-brand-600">AI</span>
          </h1>
          <p className="text-lg text-slate-500 font-medium">Empowering recovery with motion intelligence.</p>
        </div>

        <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
          <button 
            onClick={() => setIsPhysioLoggingIn(true)}
            className="group glass-card p-8 hover:bg-white hover:-translate-y-1 hover:shadow-2xl transition-all text-left flex flex-col gap-6"
          >
            <div className="w-14 h-14 bg-brand-600 rounded-2xl flex items-center justify-center text-white shadow-lg shadow-brand-600/30 group-hover:scale-110 transition-transform">
              <Stethoscope size={28} />
            </div>
            <div>
              <h3 className="font-bold text-xl text-slate-800">Clinicians</h3>
              <p className="text-sm text-slate-500 mt-1 leading-relaxed">Manage patients, monitor ROM curves, and generate AI insights.</p>
              <div className="flex items-center gap-1 text-brand-600 font-bold text-xs mt-4 group-hover:gap-2 transition-all">
                SECURE ACCESS <ChevronRight size={14} />
              </div>
            </div>
          </button>

          <button 
            onClick={() => setIsRegistering(true)}
            className="group glass-card p-8 hover:bg-white hover:-translate-y-1 hover:shadow-2xl transition-all text-left flex flex-col gap-6 border-brand-100"
          >
            <div className="w-14 h-14 bg-emerald-500 rounded-2xl flex items-center justify-center text-white shadow-lg shadow-emerald-500/30 group-hover:scale-110 transition-transform">
              <User size={28} />
            </div>
            <div>
              <h3 className="font-bold text-xl text-slate-800">Patients</h3>
              <p className="text-sm text-slate-500 mt-1 leading-relaxed">Track your exercises with camera-based motion analysis.</p>
              <div className="flex items-center gap-1 text-emerald-600 font-bold text-xs mt-4 group-hover:gap-2 transition-all">
                GET STARTED <ChevronRight size={14} />
              </div>
            </div>
          </button>
        </div>

        <div className="mt-16 text-center">
            <div className="flex items-center justify-center gap-6 opacity-30 grayscale contrast-200">
                <span className="font-bold text-slate-900 italic">HEALTH-CONNECT</span>
                <span className="font-bold text-slate-900 italic underline">AI-ASSIST</span>
                <span className="font-bold text-slate-900 italic">SECURE-LOG</span>
            </div>
            <p className="text-[10px] text-slate-400 mt-8 font-bold tracking-widest uppercase">
                Enterprise Cloud Integration • HIPAA Compliant Environment
            </p>
        </div>
      </div>
    </div>
  );
};

