    date: log.date.split('-').slice(1).join('/'),
    rom: log.maxRom,
    pain: log.painScore,
    benchmark: activePatient.benchmarkRom[Math.min(index, activePatient.benchmarkRom.length - 1)] || 0
  }));

  const handleAIAnalysis = async () => {
    setIsAnalyzing(true);
