          {patients.map(p => (
            <button key={p.id} onClick={() => setSelectedId(p.id)} className={`w-full text-left p-3 rounded-xl transition-all ${selectedId === p.id ? 'bg-brand-600 text-white shadow-lg shadow-brand-600/20' : 'hover:bg-slate-50'}`}>
              <p className="font-bold text-sm">{p.name}</p>
              <p className={`text-[10px] uppercase font-black tracking-widest ${selectedId === p.id ? 'text-white/60' : 'text-slate-400'}`}>{p.injuryType.replace('_',' ')}</p>
