import React, { useState, useRef, useEffect } from 'react';
import { Play, CheckCircle2, ChevronRight, LogOut, Activity, Sparkles, Target, TrendingUp, Calendar, BrainCircuit, Video, ArrowLeft, X, Save, Clock, PieChart as PieIcon } from 'lucide-react';
import { AreaChart, Area, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, Line, PieChart, Pie, Cell } from 'recharts';
import { Patient, Exercise, DailyLog } from '../../types';
import { getProgressBooster, analyzePatientProgress } from '../../services/geminiService';
import ReactMarkdown from 'react-markdown';

interface PatientAppProps {
  patient: Patient;
  onBack: () => void;
  onLogEntry: (log: DailyLog) => void;
}

type PatientTab = 'protocol' | 'progress';

export const PatientApp: React.FC<PatientAppProps> = ({ patient, onBack, onLogEntry }) => {
  const [activeTab, setActiveTab] = useState<PatientTab>('protocol');
  const [activeEx, setActiveEx] = useState<Exercise | null>(null);
  const [isExercising, setIsExercising] = useState(false);
  const [isFinished, setIsFinished] = useState(false);
  const [angle, setAngle] = useState(0);
  const [reps, setReps] = useState(0);
  const [pain, setPain] = useState(5);
  const [booster, setBooster] = useState("Calibrating your recovery protocol...");
  const [analysis, setAnalysis] = useState<string | null>(null);
  const [isAnalyzing, setIsAnalyzing] = useState(false);

  const videoRef = useRef<HTMLVideoElement>(null);
  const maxRomRef = useRef(0);

  useEffect(() => {
    getProgressBooster(patient).then(setBooster);
  }, [patient]);

  const triggerAIAnalysis = async () => {
    setIsAnalyzing(true);
    try {
      const result = await analyzePatientProgress(patient);
      setAnalysis(result);
    } catch (e) {
      setAnalysis("Unable to reach clinical intelligence. Please try again later.");
    } finally {
      setIsAnalyzing(false);
    }
  };

  useEffect(() => {
    let interval: any;
    if (isExercising) {
      navigator.mediaDevices.getUserMedia({ video: true })
        .then(s => { if (videoRef.current) videoRef.current.srcObject = s; })
        .catch(console.error);

      interval = setInterval(() => {
        setAngle(p => {
          const next = Math.sin(Date.now() / 800) * 40 + 40;
          if (next > maxRomRef.current) maxRomRef.current = next;
          return Math.floor(next);
        });

        if (Math.random() > 0.985) {
            setReps(r => {
                const next = r + 1;
                if (next >= (activeEx?.targetReps || 10)) {
                    setIsExercising(false);
                    setIsFinished(true);
                }
                return next;
            });
        }
      }, 100);
    } else {
        if (videoRef.current?.srcObject) (videoRef.current.srcObject as MediaStream).getTracks().forEach(t => t.stop());
    }
    return () => clearInterval(interval);
  }, [isExercising, activeEx]);

  const chartData = patient.logs.map((log, i) => ({
    date: log.date.split('-').slice(1).join('/'),
    rom: log.maxRom,
    benchmark: patient.benchmarkRom[Math.min(i, patient.benchmarkRom.length - 1)] || 0
  }));

  // Consistency Pie Chart Data
  const consistency = 88; // This would normally be calculated
  const pieData = [
    { name: 'Completed', value: consistency },
    { name: 'Missed', value: 100 - consistency },
  ];
  const COLORS = ['#2563eb', '#f1f5f9'];

  const submitLog = () => {
    onLogEntry({
      id: Date.now().toString(),
      date: new Date().toISOString().split('T')[0],
      painScore: pain,
      maxRom: Math.floor(maxRomRef.current),
      repsCompleted: reps,
      videoUrl: 'https://storage.googleapis.com/gtv-videos-bucket/sample/ForBiggerBlazes.mp4'
    });
    setIsFinished(false);
    setActiveEx(null);
  };

  if (isExercising) {
    return (
      <div className="fixed inset-0 bg-black z-50 flex flex-col">
