                            <button key={ex.id} onClick={() => { setActiveEx(ex); setIsExercising(true); }} className="w-full glass-card p-6 flex justify-between items-center hover:bg-white hover:scale-[1.02] transition-all border-l-4 border-l-brand-600 group">
                                <div className="flex items-center gap-5">
                                    <div className="w-14 h-14 bg-brand-50 text-brand-600 rounded-2xl flex items-center justify-center group-hover:bg-brand-600 group-hover:text-white transition-all"><Play size={24} fill="currentColor"/></div>
                                    <div className="text-left">
                                        <p className="font-black text-slate-800 text-lg">{ex.name}</p>
                                        <div className="flex items-center gap-3 mt-1">
                                            <span className="text-[10px] font-bold text-slate-400 uppercase tracking-widest flex items-center gap-1"><Clock size={12}/> {ex.targetReps} Reps</span>
                                            <span className="text-[10px] font-bold text-brand-600 uppercase tracking-widest flex items-center gap-1"><Target size={12}/> {ex.targetRom}°</span>
                                        </div>
                                    </div>
                                </div>
                                <ChevronRight className="text-slate-300 group-hover:translate-x-1 transition-transform"/>
                            </button>
                        ))}
                    </div>

                    <div className="grid grid-cols-2 gap-4">
                        <div className="glass-card p-6 bg-blue-50/50 border-blue-100">
                            <p className="text-[10px] font-black text-blue-400 uppercase tracking-widest mb-1">Total Logs</p>
                            <p className="text-3xl font-black text-blue-600">{patient.logs.length}</p>
