                    </div>
                </div>
            ) : (
                <div className="space-y-8 animate-in slide-in-from-bottom-4 duration-500">
                    {/* Visual Progress Charts */}
                    <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                        {/* Trajectory Graph */}
