                                        <Line type="monotone" dataKey="benchmark" stroke="#cbd5e1" strokeDasharray="6 6" dot={false} strokeWidth={2} />
                                    </AreaChart>
                                </ResponsiveContainer>
                            </div>
                        </div>

                        {/* Consistency Pie Chart */}
                        <div className="glass-card p-8 flex flex-col items-center">
